import os
import csv
from openpyxl import load_workbook

def task_func(file_name, excel_file_path, csv_file_path) -> str:
    if not file_name:
        raise ValueError("file_name must be a non-empty string")

    source_file = os.path.join(excel_file_path or "", file_name)
    if not os.path.isfile(source_file):
        raise FileNotFoundError(f"Excel file not found: {source_file}")

    base_name, ext = os.path.splitext(os.path.basename(file_name))
    if ext.lower() not in {".xls", ".xlsx"}:
        raise ValueError("file_name must have a .xls or .xlsx extension")

    csv_name = base_name + ".csv"
    destination_dir = csv_file_path or ""
    if destination_dir:
        os.makedirs(destination_dir, exist_ok=True)
    destination_file = os.path.join(destination_dir, csv_name)

    if ext.lower() == ".xls":
        try:
            import xlrd
        except ImportError as exc:
            raise ImportError("Converting .xls files requires the optional 'xlrd' package") from exc

        workbook = xlrd.open_workbook(source_file)
        sheet = workbook.sheet_by_index(0)
        with open(destination_file, "w", newline="", encoding="utf-8") as csv_file:
            writer = csv.writer(csv_file)
            for row_index in range(sheet.nrows):
                writer.writerow(sheet.row_values(row_index))
    else:
        workbook = load_workbook(source_file, read_only=True, data_only=False)
        try:
            sheet = workbook.active
            with open(destination_file, "w", newline="", encoding="utf-8") as csv_file:
                writer = csv.writer(csv_file)
                for row in sheet.iter_rows(values_only=True):
                    writer.writerow(row)
        finally:
            workbook.close()

    return csv_name
